const id = 'd1-l01'
export const lesson: Lesson = {
  id, number: 1, domainId: 1, chapterId: '1.1',
  title: 'Thiết kế luồng CI/CD với CodePipeline',
  summary: 'Hiểu cách CodePipeline đưa một thay đổi từ mã nguồn đến bản phát hành: xác định đúng phiên bản, chuyển giao gói phần mềm, sắp xếp các bước kiểm tra và kiểm soát những lần chạy chồng nhau.',
  duration: 90,
  objectives: ['Phân biệt tích hợp liên tục, phân phối liên tục và triển khai liên tục qua cách quyết định phát hành.', 'Thiết kế các giai đoạn và đường chuyển giao gói phần mềm để có thể xác định nguồn gốc của từng bản phát hành.', 'Chọn chế độ thực thi phù hợp với tài nguyên dùng chung, yêu cầu về thứ tự và khả năng khôi phục.'],
  prerequisites: ['Đã biết commit trong Git, vai trò của IAM role và cách sử dụng S3 bucket ở mức Associate.'],
  sections: [
    { id: `${id}-purpose`, title: '1. Phần mềm đi từ commit đến môi trường vận hành như thế nào?', paragraphs: [
      'Continuous integration (tích hợp liên tục, gọi tắt là CI) là cách nhóm thường xuyên đưa những thay đổi nhỏ vào nhánh mã nguồn chung rồi tự động kiểm tra chúng. Chẳng hạn, mỗi lần gộp mã, hệ thống biên dịch ứng dụng và chạy bộ kiểm thử. Nếu các bước này thành công, nhóm biết thay đổi vừa được tích hợp đáp ứng những kiểm tra đã đặt ra; ứng dụng chưa nhất thiết được đưa đến người dùng. Continuous delivery (phân phối liên tục) đi xa hơn: quy trình luôn chuẩn bị được một phiên bản đủ điều kiện phát hành, nhưng việc đưa phiên bản đó vào production (môi trường vận hành chính thức) vẫn có thể cần người quyết định. Continuous deployment (triển khai liên tục) tự động đưa phiên bản đã vượt qua các kiểm tra vào môi trường chính thức. Điểm cần phân biệt là ai quyết định bước phát hành cuối cùng, chứ không chỉ là quy trình có chạy kiểm thử tự động hay không.',
      'Trong quy trình đó, CodePipeline giữ vai trò điều phối: nó khởi động từng công việc, chuyển đầu ra sang bước tiếp theo và theo dõi kết quả. CodeBuild thực sự chạy các lệnh build (biên dịch, chuẩn bị gói phần mềm) và kiểm thử; CodeDeploy hoặc công cụ triển khai tương ứng đưa gói phần mềm vào môi trường chạy ứng dụng. Hiểu rõ ai làm việc gì sẽ giúp bạn tìm đúng nơi khi có lỗi. Nếu trình biên dịch báo lỗi, hãy xem nhật ký của CodeBuild; nếu bước sau không nhận được gói đầu vào, hãy kiểm tra cách nối các bước trong CodePipeline. Ví dụ, một nhóm thương mại điện tử có thể tự động kiểm tra và triển khai đến môi trường thử nghiệm, sau đó chờ người phụ trách duyệt trước khi phát hành. Một nhóm vận hành trang thông báo nội bộ có thể tự động phát hành sau khi đã xây dựng được các kiểm tra và phương án khôi phục đáng tin cậy. Khi làm bài thi, hãy đối chiếu thiết kế với yêu cầu phê duyệt, mức rủi ro và thời gian chờ được chấp nhận trong tình huống.'
    ] },
    { id: `${id}-contract`, title: '2. Chuyển giao đúng gói phần mềm và xác định nguồn gốc bản phát hành', paragraphs: [
      'Artifact (gói dữ liệu đầu ra) là tập tin hoặc tập hợp tập tin mà một bước chuyển cho bước tiếp theo. Đó có thể là mã nguồn nén trong ZIP, website đã biên dịch hoặc mẫu cấu hình hạ tầng. Một action (tác vụ trong CodePipeline) khai báo tên gói đầu ra; action sử dụng gói đó phải khai báo đúng tên ở phần đầu vào. Ví dụ, nếu bước lấy mã nguồn xuất SourceBundle, bước biên dịch phải nhận SourceBundle. Đây là tên dùng để nối dữ liệu trong pipeline, không phải tên một thư mục trong kho mã nguồn. Artifact store (kho lưu gói dữ liệu) trên S3 lưu và chuyển các gói này giữa những tác vụ. Cách làm đáng tin cậy là build một lần, kiểm tra gói vừa tạo rồi đưa chính gói đó lần lượt qua các môi trường. Quá trình này thường gọi là promote. Nếu mỗi môi trường lại build riêng, một thư viện phụ thuộc vừa được cập nhật có thể khiến gói ở môi trường chính thức khác gói đã kiểm tra, dù cả hai dùng cùng một commit.',
      'Để điều tra một bản phát hành, bạn cần phân biệt mã nguồn đã chọn với lần chạy đã tạo ra bản đó. Source revision (phiên bản mã nguồn) cho biết commit hoặc phiên bản đối tượng nguồn; execution ID (mã lần thực thi) xác định một lần CodePipeline chạy. Cùng một commit có thể được chạy nhiều lần, với nhật ký, kết quả kiểm tra và quyết định phê duyệt riêng. Vì vậy, manifest (tập tin mô tả bản phát hành) nên ghi commit SHA, checksum của gói hoặc image digest, mã lần thực thi và đường dẫn đến báo cáo kiểm thử. Kết hợp thông tin này với lịch sử phê duyệt, bạn có thể xác định bản nào đang chạy và căn cứ nào đã được dùng để cho phép phát hành. Với những giá trị nhỏ như commit SHA, action có thể xuất biến trong một namespace (không gian tên biến), để bước sau tham chiếu qua cú pháp #{SourceVariables.CommitId}. Biến phù hợp để truyền thông tin mô tả; tập tin vẫn cần đi qua gói dữ liệu. Không đưa bí mật truy cập vào những biến có thể hiển thị trong lịch sử thực thi.'
    ] },
    { id: `${id}-ordering`, title: '3. Sắp xếp các tác vụ theo dữ liệu mà chúng cần', paragraphs: [
      'Stage (giai đoạn) tập hợp những tác vụ cùng phục vụ một mục đích, chẳng hạn biên dịch, xác minh hoặc triển khai đến môi trường chính thức. Trong cùng một giai đoạn, các action có cùng runOrder có thể chạy song song. Nhóm có runOrder lớn hơn chỉ bắt đầu sau khi nhóm có số nhỏ hơn hoàn thành thành công. Ví dụ, lint (kiểm tra quy tắc viết mã) và unit test (kiểm thử đơn vị) không phụ thuộc nhau nên có thể cùng nhận runOrder = 1. Nếu chỉ được đóng gói khi cả hai kiểm tra đều đạt, hãy đặt bước đóng gói ở runOrder = 2. Bạn cần khai báo cả thứ tự thực thi lẫn gói đầu vào phù hợp: một bước quét bảo mật cần chương trình đã biên dịch thì phải nhận đầu ra của bước biên dịch và chạy sau bước đó. Vị trí các ô trên sơ đồ không thay thế những khai báo này.',
      'Chạy song song giúp rút ngắn thời gian khi các công việc thực sự độc lập. Tuy nhiên, CodePipeline không tự tách tài nguyên mà ứng dụng dùng để kiểm thử. Hai integration test (kiểm thử tích hợp) cùng sửa một bản ghi trong cơ sở dữ liệu vẫn có thể ghi đè lên nhau, dù cấu hình pipeline hoàn toàn hợp lệ. Hãy cấp dữ liệu riêng cho từng lần chạy, hoặc dùng môi trường thử riêng nếu cần cô lập cả tài nguyên. Bạn cũng cần kiểm tra ý nghĩa của trạng thái thành công: một script bắt mọi lỗi rồi trả mã thoát 0 sẽ khiến pipeline báo thành công dù kiểm thử đã thất bại. Quality gate (điều kiện kiểm tra trước khi đi tiếp) chỉ có ích khi kết quả của nó phản ánh đúng điều cần xác minh. Vì vậy, hãy thiết kế giai đoạn theo quyết định cần đưa ra và dữ liệu cần có, rồi mới tìm các bước có thể chạy song song.'
    ] },
    { id: `${id}-concurrency`, title: '4. Chọn chế độ thực thi khi nhiều thay đổi đến liên tiếp', paragraphs: [
      'Execution mode (chế độ thực thi) quyết định CodePipeline xử lý thế nào khi nhiều lần chạy cùng tồn tại. SUPERSEDED phù hợp khi nhóm chỉ cần phát hành phiên bản mới nhất và chấp nhận bỏ qua một số lần chạy cũ còn đang chờ. Lần chạy mới có thể vượt và thay thế lần cũ tại các điểm mà dịch vụ cho phép; điều này không có nghĩa mọi lệnh build đang chạy đều bị hủy ngay. QUEUED đưa các lần chạy vào hàng đợi để xử lý tuần tự. Chế độ này phù hợp nếu mọi bản phát hành đều phải được xử lý đúng thứ tự, chẳng hạn bản sau cần phần dữ liệu do bản trước bổ sung. PARALLEL cho nhiều lần chạy tiến hành đồng thời, thích hợp với các môi trường xem trước được tạo riêng cho từng thay đổi. Nếu cùng triển khai đến một môi trường dùng chung, bản cũ có thể hoàn tất sau bản mới và ghi đè kết quả mới hơn. QUEUED và PARALLEL yêu cầu pipeline loại V2.',
      'Chế độ thực thi chỉ kiểm soát việc chạy pipeline; nó không tự làm cho thay đổi dữ liệu trở nên an toàn. Migration (bước chuyển đổi cấu trúc hoặc dữ liệu) có thể khiến phiên bản ứng dụng cũ không còn đọc được cơ sở dữ liệu, ngay cả khi các bản phát hành được xếp hàng đúng thứ tự. Trước khi chọn chế độ, hãy xác định tài nguyên nào được dùng chung và ứng dụng cũ có còn chạy được sau thay đổi hay không. Bạn cũng cần tính đến rollback (khôi phục về phiên bản trước): PARALLEL không hỗ trợ khôi phục ở cấp giai đoạn và không cho cấu hình failure condition với kết quả rollback. Nếu yêu cầu phụ thuộc vào tính năng khôi phục này, hãy chọn chế độ khác hoặc thiết kế, kiểm chứng một phương án phục hồi riêng. Việc build song song có thể tiết kiệm vài phút, nhưng quyết định triển khai song song phải dựa thêm vào thứ tự cập nhật và khả năng phục hồi của hệ thống.'
    ] },
    { id: `${id}-gates`, title: '5. Phê duyệt phát hành, tìm lỗi và khôi phục', paragraphs: [
      'Manual approval (phê duyệt thủ công) là tác vụ tạm dừng quy trình để người có quyền IAM chấp thuận hoặc từ chối cho đi tiếp. Bước này phù hợp khi cần người phụ trách nghiệp vụ chấp nhận rủi ro hoặc xem xét báo cáo kiểm định trước khi phát hành. Để quyết định có cơ sở, người duyệt phải biết phiên bản mã nguồn nào đang chờ, gói phần mềm đó đã vượt qua những kiểm tra nào và sẽ được triển khai đến đâu. Hãy đưa đường dẫn đến báo cáo và thông tin phiên bản vào nội dung phê duyệt, đồng thời cấu hình thông báo SNS đến đúng người. Việc thêm một ô phê duyệt không tự chạy thêm kiểm thử và cũng chưa đủ chứng minh người tạo thay đổi được tách biệt với người duyệt; quyền IAM phải thể hiện yêu cầu đó. Nếu hết thời gian chờ mà chưa được duyệt, tác vụ sẽ thất bại theo giới hạn và cấu hình của dịch vụ.',
      'Khi pipeline thất bại, hãy mở đúng lần thực thi, xác định tác vụ lỗi và đối chiếu gói đầu vào trước khi đọc nhật ký của dịch vụ thực hiện công việc. Retry (thử lại) phù hợp khi bạn đã hiểu nguyên nhân tạm thời, chẳng hạn đầu cuối dịch vụ bị gián đoạn và hiện đã hoạt động trở lại. Trước khi thử lại, kiểm tra xem lần triển khai dở dang có thay đổi dữ liệu hoặc tài nguyên nào chưa, để tránh lặp một thao tác gây tác động lần nữa. Việc dừng pipeline chỉ ngăn quy trình tiếp tục theo cách dừng đã chọn; nó không tự hoàn tác thay đổi đã xảy ra. Tương tự, khôi phục phiên bản ứng dụng không đương nhiên phục hồi mọi thay đổi trong cơ sở dữ liệu. Kế hoạch phục hồi cần chỉ rõ gói phiên bản trước, tiêu chí xác nhận ứng dụng hoạt động bình thường, người có quyền thực hiện và cách phối hợp khi có sự cố. Sau khi khôi phục, hãy cập nhật điều kiện kiểm tra hoặc runbook (hướng dẫn xử lý sự cố) để lần sau phát hiện hay xử lý được nguyên nhân sớm hơn.'
    ] },
  ],
  diagram: { title: 'Theo dõi một phiên bản từ mã nguồn đến môi trường chính thức', steps: [
    { label: 'Chọn mã nguồn', detail: 'Ghi nhận commit SHA của phiên bản sẽ phát hành.' },
    { label: 'Build và kiểm thử đơn vị', detail: 'Tạo gói phần mềm cùng tập tin mô tả nguồn gốc.' },
    { label: 'Kiểm tra ở môi trường tiền triển khai', detail: 'Thử nghiệm chính gói sẽ đưa vào môi trường chính thức.' },
    { label: 'Phê duyệt', detail: 'Người duyệt đối chiếu phiên bản, báo cáo kiểm thử và môi trường đích.' },
    { label: 'Triển khai và theo dõi', detail: 'Theo dõi sau triển khai; khôi phục phiên bản trước nếu tỷ lệ lỗi vượt ngưỡng cho phép.' },
  ], caption: 'Mỗi lần chạy gắn với một phiên bản nguồn. Gói phần mềm được tạo một lần, kiểm tra rồi chuyển tiếp; báo cáo và lịch sử phê duyệt phải cho biết chúng thuộc đúng gói đó.' },
  scenarios: [
    { title: 'Các bước chuyển đổi dữ liệu cần chạy đúng thứ tự', context: 'Dịch vụ đặt vé có hai bản phát hành liên tiếp. Bản sau cần dữ liệu do bản trước bổ sung, nên cả hai đều phải được triển khai.', solution: 'Chọn QUEUED để xếp hàng các lần chạy. Đánh phiên bản cho gói chuyển đổi dữ liệu, kiểm tra bước nào đã chạy và giữ cấu trúc dữ liệu tương thích với các phiên bản ứng dụng trong giai đoạn chuyển tiếp.', tradeoff: 'Hàng đợi dài sẽ làm bản mới phải chờ lâu hơn. Nếu dùng PARALLEL với cùng cơ sở dữ liệu, nhóm phải tự giải quyết nguy cơ các bước cập nhật kết thúc sai thứ tự.' },
    { title: 'Tạo môi trường xem trước cho từng pull request', context: 'Nhóm phát triển giao diện muốn có năm môi trường xem trước cùng lúc và tự dọn chúng sau khi hoàn tất xem xét mã.', solution: 'Chọn PARALLEL và đặt tên stack, URL cùng gói đầu ra riêng cho từng lần chạy. Tách dữ liệu thử giữa các môi trường và giới hạn số lần chạy đồng thời theo hạn mức tài khoản.', tradeoff: 'Mỗi môi trường cần thêm tài nguyên và chi phí. Nhóm cũng cần phương án phục hồi riêng vì PARALLEL không hỗ trợ khôi phục ở cấp giai đoạn.' },
  ],
  keyTakeaways: ['CodePipeline điều phối các bước; CodeBuild và các dịch vụ triển khai trực tiếp thực hiện công việc.', 'Đưa chính gói đã kiểm thử qua các môi trường và lưu đủ thông tin để xác định nguồn gốc từng bản phát hành.', 'runOrder sắp xếp tác vụ trong một giai đoạn; execution mode kiểm soát cách nhiều lần chạy cùng tiến hành.', 'Phê duyệt cần thông tin về phiên bản và kết quả kiểm tra để người duyệt đưa ra quyết định có cơ sở.'],
  examTraps: ['SUPERSEDED cho phép bỏ qua một số lần chạy đang chờ, nên không đáp ứng yêu cầu triển khai mọi commit.', 'Với PARALLEL, hai lần triển khai đến cùng môi trường chính thức có thể hoàn tất khác thứ tự bắt đầu.', 'Dừng pipeline không tự hoàn tác dữ liệu hay tài nguyên đã thay đổi.', 'Hai gói được build lại từ cùng Git SHA vẫn có thể khác nội dung nếu các thành phần phụ thuộc đã đổi.'],
  code: {
    title: 'Khung pipeline xếp hàng: đọc cấu trúc trước khi bổ sung hạ tầng', deployable: false,
    cloudformation: `Resources:
  ReleasePipeline:
    Type: AWS::CodePipeline::Pipeline
    Properties:
      PipelineType: V2
      ExecutionMode: QUEUED
      RoleArn: !GetAtt PipelineRole.Arn
      ArtifactStore:
        Type: S3
        Location: !Ref ArtifactBucket
      Stages:
        - Name: Source
          Actions:
            - Name: Fetch
              ActionTypeId: {Category: Source, Owner: AWS, Provider: CodeStarSourceConnection, Version: '1'}
              Configuration:
                ConnectionArn: !Ref ConnectionArn
                FullRepositoryId: team/application
                BranchName: main
              OutputArtifacts: [{Name: SourceBundle}]
        - Name: Build
          Actions:
            - Name: Compile
              ActionTypeId: {Category: Build, Owner: AWS, Provider: CodeBuild, Version: '1'}
              InputArtifacts: [{Name: SourceBundle}]
              OutputArtifacts: [{Name: ReleaseBundle}]
              Configuration: {ProjectName: !Ref BuildProject}`,
    terraform: `resource "aws_codepipeline" "release" {
  name           = "study-release"
  pipeline_type  = "V2"
  execution_mode = "QUEUED"
  role_arn       = aws_iam_role.pipeline.arn
  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"
  }
  # Add source/build stages, connection, project and scoped IAM policies.
}`,
    explanation: 'Đây là hai đoạn minh họa cấu trúc, chưa đủ để triển khai: bạn còn cần IAM role, S3 bucket, kết nối kho mã nguồn đã được xác thực và dự án CodeBuild. Trong CloudFormation, hãy chú ý Source xuất SourceBundle và Build nhận đúng tên gói đó. Đoạn Terraform cho thấy cách khai báo pipeline loại V2 cùng chế độ QUEUED. Bài thực hành bên dưới hướng dẫn tạo các tài nguyên còn thiếu trên bảng điều khiển AWS để bạn hiểu vai trò của từng thành phần.'
  },
  lab: {
    title: 'Theo dõi hai phiên bản mã nguồn qua một pipeline nhỏ', duration: 60,
    prerequisites: ['Có tài khoản AWS thử nghiệm với quyền tạo CodePipeline, CodeBuild, S3 và các service role được giới hạn quyền phù hợp.', 'Có kho mã nguồn thử thuộc quyền quản lý của bạn, chứa một ứng dụng nhỏ và lệnh kiểm thử; chủ sở hữu đã xác thực kết nối đến kho.', 'Sử dụng mã nguồn và dữ liệu dành riêng cho thực hành.'],
    cost: 'CodePipeline, thời gian chạy CodeBuild, dung lượng lưu gói trên S3 và CloudWatch Logs có thể phát sinh phí. Hãy xem giá tại Region đã chọn, đặt thời hạn lưu nhật ký và dọn tài nguyên sau bài thực hành.',
    steps: [
      { title: 'Xác nhận tài khoản thử nghiệm', detail: 'Chọn một Region. Trước khi tạo tài nguyên, ghi lại mã tài khoản, tên pipeline study-release và kho mã nguồn sẽ dùng.', command: 'aws sts get-caller-identity', expected: 'Giá trị Account khớp tài khoản thử nghiệm dự kiến; kết quả lệnh không chứa khóa truy cập bí mật.' },
      { title: 'Tạo dự án CodeBuild', detail: 'Trong CodeBuild, chọn CodePipeline cho nguồn và đầu ra, chọn managed image phù hợp với ứng dụng. Viết buildspec chạy kiểm thử rồi đóng gói ứng dụng, đồng thời đặt thời gian chạy tối đa.', expected: 'Dự án có service role riêng. buildspec chỉ rõ thư mục chứa các tập tin sẽ đưa vào gói đầu ra.' },
      { title: 'Tạo pipeline', detail: 'Trên bảng điều khiển AWS, tạo pipeline loại V2 với chế độ QUEUED. Kết nối nguồn đến nhánh thử nghiệm và nối tác vụ build đến dự án vừa tạo. Dùng SourceBundle cho gói mã nguồn, ReleaseBundle cho gói sau build.', expected: 'Lần chạy đầu hiển thị phiên bản mã nguồn và hoàn thành bước build. S3 lưu gói dữ liệu gắn với lần chạy đó.' },
      { title: 'Thêm bước phê duyệt để quan sát hàng đợi', detail: 'Thêm manual approval sau bước build. Đưa đường dẫn đến báo cáo và commit vào nội dung duyệt. Đẩy hai commit thử lên kho rồi mở lịch sử thực thi.', expected: 'Lần chạy sau phải chờ theo chế độ QUEUED. Mỗi yêu cầu phê duyệt hiển thị đúng phiên bản đang được xử lý.' },
      { title: 'Chủ động tạo một kiểm thử thất bại', detail: 'Trên nhánh thử nghiệm, sửa một điều kiện kiểm tra để lệnh kiểm thử trả mã thoát khác 0. Đọc nhật ký CodeBuild để tìm lỗi, sau đó sửa lại bằng một commit mới.', expected: 'Lần chạy có lỗi dừng trước bước phê duyệt. Commit sửa lỗi tạo lần chạy khác và bạn có thể lần từ đó đến nhật ký tương ứng.' },
      { title: 'Đối chiếu nguồn gốc gói phần mềm', detail: 'Mở một lần chạy thành công và so commit trong tập tin mô tả gói với phiên bản nguồn của lần chạy. Giải thích vì sao nên đưa chính gói này sang môi trường tiếp theo thay vì build lại.', command: 'aws codepipeline list-pipeline-executions --pipeline-name study-release --max-results 5', expected: 'Danh sách hiển thị mã lần thực thi, trạng thái và phiên bản nguồn. Bạn phân biệt được các lần chạy ngay cả khi chúng sử dụng cùng commit.' },
    ],
    cleanup: ['Dừng các lần thực thi còn chờ, rồi xóa pipeline study-release trên bảng điều khiển AWS.', 'Xóa dự án CodeBuild thử nghiệm và nhóm nhật ký tương ứng nếu bạn không cần giữ kết quả thực hành.', 'Xác nhận đúng S3 bucket lưu gói của bài thực hành. Xóa các đối tượng và phiên bản trong bucket đó, sau đó xóa bucket trên bảng điều khiển AWS.', 'Chỉ xóa IAM role và kết nối kho mã nguồn nếu chúng được tạo riêng cho bài thực hành và không còn tài nguyên khác sử dụng.'],
    challenge: 'Tạo bản sao của pipeline rồi chuyển sang PARALLEL để phục vụ các môi trường xem trước độc lập. Giải thích vì sao cách tăng tốc này không phù hợp nếu các lần chạy cùng chuyển đổi dữ liệu trong một cơ sở dữ liệu chính thức.'
  },
  sources: [
    { title: 'AWS exam guide: Domain 1', url: 'https://docs.aws.amazon.com/aws-certification/latest/devops-engineer-professional-02/devops-engineer-professional-02-domain1.html' },
    { title: 'CodePipeline concepts', url: 'https://docs.aws.amazon.com/codepipeline/latest/userguide/concepts.html' },
    { title: 'Action declaration and runOrder', url: 'https://docs.aws.amazon.com/codepipeline/latest/userguide/action-requirements.html' },
    { title: 'Execution modes and rollback limitations', url: 'https://docs.aws.amazon.com/codepipeline/latest/userguide/execution-modes.html' },
    { title: 'Manual approval actions', url: 'https://docs.aws.amazon.com/codepipeline/latest/userguide/approvals.html' },
  ], reviewedAt: '2026-10-19',
  questions: questions(id, '1.1', [
    { section: 'purpose', en: 'A team builds and tests every merge but requires a risk owner to authorize production. Which delivery model does this represent?', vi: 'Một nhóm tự động build và kiểm thử mỗi lần gộp mã. Tuy nhiên, trước khi triển khai vào môi trường chính thức, người chịu trách nhiệm về rủi ro phải cho phép phát hành. Nhóm đang áp dụng mô hình nào?', options: [
      ['Continuous delivery', 'Phân phối liên tục', 'Đúng. Quy trình tự động chuẩn bị phần mềm để sẵn sàng phát hành, còn quyết định đưa vào môi trường chính thức vẫn thuộc về người có trách nhiệm.'], ['Continuous deployment', 'Triển khai liên tục', 'Sai. Triển khai liên tục tự động phát hành khi các kiểm tra đều đạt. Yêu cầu bắt buộc phải có người duyệt trong tình huống này tạo ra một điểm quyết định thủ công.'], ['Continuous integration without a delivery process', 'Tích hợp liên tục nhưng chưa có quy trình phân phối phần mềm', 'Sai. Nhóm không chỉ tích hợp và kiểm thử mã; họ còn có quy trình đưa bản đã chuẩn bị đến bước quyết định phát hành. Tích hợp liên tục là một phần của quy trình đó.'], ['A manual release process without automated integration', 'Phát hành thủ công và không tích hợp mã tự động', 'Sai. Các bước build và kiểm thử đã được tự động hóa mỗi lần gộp mã. Việc cần người quyết định ở bước cuối không làm mất phần tích hợp tự động này.'],
    ], correct: ['A'], explanation: 'Điểm phân biệt là quyết định phát hành cuối cùng. Phần mềm được chuẩn bị tự động nhưng vẫn chờ người duyệt, nên đây là phân phối liên tục.', tags: ['CI/CD', 'delivery'], difficulty: 'associate-refresh' },
    { section: 'purpose', en: 'A pipeline action reports a failed compiler invocation. Which service log should the engineer examine first when CodeBuild executes compilation?', vi: 'Một tác vụ trong pipeline báo lỗi khi gọi trình biên dịch. CodeBuild là dịch vụ chạy lệnh biên dịch đó. Kỹ sư nên xem nhật ký nào trước tiên?', options: [
      ['The corresponding CodeBuild build log', 'Nhật ký của lần build CodeBuild bị lỗi', 'Đúng. CodeBuild trực tiếp chạy lệnh nên nhật ký của lần build tương ứng chứa thông báo từ trình biên dịch và mã thoát cần để tìm nguyên nhân.'], ['Only S3 artifact access logs', 'Chỉ nhật ký truy cập gói dữ liệu trên S3', 'Sai. Nhật ký S3 hữu ích khi điều tra việc tải lên hoặc tải xuống gói dữ liệu, nhưng không chứa chẩn đoán do trình biên dịch tạo ra.'], ['Only the CodePipeline execution summary', 'Chỉ bản tóm tắt lần thực thi CodePipeline', 'Sai. Bản tóm tắt giúp tìm tác vụ thất bại và liên kết đến lần build. Để sửa lỗi biên dịch, kỹ sư vẫn cần thông báo chi tiết từ CodeBuild.'], ['Only the last successful deployment agent log', 'Chỉ nhật ký của tác nhân triển khai trong lần thành công trước', 'Sai. Nhật ký đó thuộc lần triển khai trước và không phản ánh lệnh biên dịch đang thất bại trong lần chạy hiện tại.'],
    ], correct: ['A'], explanation: 'Từ CodePipeline, tìm mã lần build bị lỗi rồi mở nhật ký CodeBuild tương ứng. Cách này nối được lỗi tổng quát trên pipeline với thông báo cụ thể từ trình biên dịch.', tags: ['CodeBuild', 'troubleshooting'] },
    { section: 'contract', en: 'Staging passes, but production rebuilt from the same commit contains a newer transitive dependency. What best prevents this mismatch?', vi: 'Ứng dụng đã vượt qua kiểm thử ở môi trường tiền triển khai. Khi build lại từ cùng commit để phát hành chính thức, gói mới lại chứa phiên bản mới hơn của một thư viện phụ thuộc gián tiếp. Cách nào ngăn sự khác biệt này hiệu quả nhất?', options: [
      ['Promote the tested immutable artifact', 'Đưa chính gói đã kiểm thử, được giữ nguyên nội dung, vào môi trường chính thức', 'Đúng. Môi trường chính thức nhận đúng nội dung đã qua kiểm thử, nên không phát sinh khác biệt do tải lại thư viện trong một lần build khác.'], ['Add approval while rebuilding independently in production', 'Thêm bước phê duyệt nhưng vẫn build riêng cho môi trường chính thức', 'Sai. Người duyệt có thể cho phép phát hành, nhưng sự phê duyệt không bảo đảm gói build lại có cùng nội dung với gói đã kiểm thử.'], ['Require a second manual rebuild', 'Yêu cầu build lại thủ công lần thứ hai', 'Sai. Một lần build bổ sung vẫn có thể lấy thư viện khác phiên bản; việc chạy thủ công không cố định nội dung đầu ra.'], ['Use the same branch name as proof of binary equivalence', 'Dùng tên nhánh giống nhau để chứng minh hai gói biên dịch tương đương', 'Sai. Tên nhánh không cố định commit và cũng không cố định các thư viện được tải lúc build, nên không chứng minh hai gói giống nhau.'],
    ], correct: ['A'], explanation: 'Build một lần rồi đưa cùng gói qua các môi trường loại bỏ sai khác do build lại. Cấu hình dành riêng cho từng môi trường vẫn phải được quản lý phù hợp.', tags: ['artifact', 'immutability'] },
    { section: 'contract', en: 'A build action expects input AppSource, while the source action outputs SourceBundle. What must change?', vi: 'Tác vụ build yêu cầu gói đầu vào tên AppSource, nhưng tác vụ lấy mã nguồn xuất gói tên SourceBundle. Cần điều chỉnh gì để hai bước nối được với nhau?', options: [
      ['Align the input artifact name with the source output', 'Sửa tên gói đầu vào cho khớp tên đầu ra của bước lấy mã nguồn', 'Đúng. CodePipeline dùng tên đã khai báo để nối đầu ra với đầu vào. Bước build phải nhận SourceBundle nếu đó là gói bước trước xuất ra.'], ['Rename the repository directory to AppSource', 'Đổi tên thư mục trong kho mã nguồn thành AppSource', 'Sai. Tên thư mục nằm trong nội dung gói, còn tên gói được khai báo riêng trong cấu hình pipeline. Đổi thư mục không sửa được chỗ nối bị sai.'], ['Change only artifacts.base-directory inside the buildspec', 'Chỉ đổi artifacts.base-directory trong buildspec', 'Sai. Thuộc tính này chỉ vị trí tập tin để tạo đầu ra build. Lỗi hiện tại xảy ra ở tên gói đầu vào mà CodePipeline cần cung cấp trước khi build chạy.'], ['Change the build output name but leave its input unchanged', 'Đổi tên gói đầu ra của bước build và giữ nguyên đầu vào', 'Sai. Bước build vẫn yêu cầu AppSource, trong khi không có bước trước nào xuất gói tên đó; sửa đầu ra không giải quyết được đầu vào còn thiếu.'],
    ], correct: ['A'], explanation: 'Hãy kiểm tra tên gói trong khai báo pipeline trước. Tên đó xác định đường chuyển giao dữ liệu giữa các tác vụ và độc lập với đường dẫn tập tin bên trong gói.', tags: ['artifact', 'CodePipeline'] },
    { section: 'contract', en: 'An auditor must identify both the exact container content and the release attempt. Which TWO identifiers should be retained? Choose two.', vi: 'Người kiểm toán cần xác định chính xác nội dung image được triển khai và lần phát hành đã sử dụng image đó. Cần lưu hai thông tin nào? Chọn hai đáp án.', options: [
      ['Container image digest', 'Digest của container image', 'Đúng. Digest được tính từ nội dung image, nên giúp xác định chính xác image thay vì dựa vào một nhãn có thể được gán sang nội dung khác.'], ['Pipeline execution ID', 'Mã lần thực thi pipeline', 'Đúng. Mã này phân biệt các lần phát hành, kể cả khi chúng cùng dùng một phiên bản mã nguồn hoặc cùng một image.'], ['Only the branch name', 'Chỉ tên nhánh mã nguồn', 'Sai. Một nhánh có thể trỏ đến nhiều commit theo thời gian; tên nhánh không xác định nội dung image hay lần phát hành cụ thể.'], ['Only the deployment stage name', 'Chỉ tên giai đoạn triển khai', 'Sai. Cùng một giai đoạn được dùng cho nhiều lần phát hành, nên tên của nó không xác định lần chạy hay nội dung đã triển khai.'], ['The current latest tag alone', 'Chỉ nhãn latest hiện tại', 'Sai. Nhãn latest có thể được gán lại sau mỗi lần build. Giá trị hiện tại không đủ chứng minh image nào đã được dùng trong quá khứ.'],
    ], correct: ['A', 'B'], explanation: 'Digest trả lời câu hỏi image chứa nội dung nào; execution ID trả lời lần chạy nào đã phát hành nó. Cần cả hai để đối chiếu nội dung với lịch sử triển khai.', tags: ['traceability', 'digest'] },
    { section: 'contract', en: 'A downstream action needs a small commit ID value, not source files. Which mechanism is most appropriate?', vi: 'Một tác vụ ở bước sau chỉ cần mã commit để đưa vào cấu hình, không cần nhận tập tin mã nguồn. Nên truyền giá trị này bằng cơ chế nào?', options: [
      ['A namespaced source output variable', 'Biến đầu ra của bước lấy mã nguồn, được đặt trong một namespace', 'Đúng. Biến đầu ra chuyển được thông tin mô tả nhỏ như commit ID đến cấu hình bước sau, đồng thời giữ giá trị gắn với phiên bản đã chọn cho lần chạy.'], ['Parse the current branch tip in a later independent Git request', 'Gọi Git riêng ở bước sau để đọc commit mới nhất của nhánh', 'Sai. Nhánh có thể đã nhận commit mới khi lệnh này chạy; kết quả khi đó không còn là phiên bản mà tác vụ nguồn đã chọn cho pipeline.'], ['Rebuild the source to discover the commit value', 'Build lại mã nguồn để tìm mã commit', 'Sai. Tác vụ nguồn đã cung cấp thông tin cần thiết. Build lại thêm công việc và có thể tạo gói khác mà không giúp xác định phiên bản chính xác hơn.'], ['Use the pipeline execution ID as if it were the commit SHA', 'Dùng mã lần thực thi pipeline thay cho commit SHA', 'Sai. Mã lần thực thi xác định một lần chạy, còn commit SHA xác định phiên bản mã nguồn. Hai giá trị có mục đích khác nhau và không thay thế được cho nhau.'],
    ], correct: ['A'], explanation: 'Biến đầu ra phù hợp với thông tin nhỏ như commit ID; gói dữ liệu dùng để chuyển tập tin. Với bí mật truy cập, cần dùng cơ chế quản lý bí mật thay vì biến có thể hiển thị trong lịch sử.', tags: ['variables', 'source'] },
    { section: 'ordering', en: 'Lint and unit tests are independent; packaging requires both to pass. Which runOrder arrangement is correct within one stage?', vi: 'Kiểm tra quy tắc mã bằng lint và kiểm thử đơn vị có thể chạy độc lập. Bước đóng gói chỉ được bắt đầu khi cả hai đều đạt. Trong cùng một giai đoạn, nên đặt runOrder thế nào?', options: [
      ['Lint=1, unit=1, package=2', 'Lint=1, unit=1, package=2', 'Đúng. Hai bước kiểm tra cùng thuộc nhóm 1 nên có thể chạy song song. Bước đóng gói ở nhóm 2 phải chờ cả nhóm 1 hoàn thành thành công.'], ['Lint=1, unit=2, package=1', 'Lint=1, unit=2, package=1', 'Sai. Bước đóng gói ở nhóm 1 có thể chạy trước khi kiểm thử đơn vị ở nhóm 2 bắt đầu, nên không đáp ứng yêu cầu chờ cả hai kiểm tra.'], ['All actions use runOrder=1', 'Tất cả tác vụ đều dùng runOrder=1', 'Sai. Cả ba tác vụ có thể bắt đầu cùng nhóm; bước đóng gói không được buộc chờ hai kiểm tra hoàn tất.'], ['Lint=3, unit=3, package=2', 'Lint=3, unit=3, package=2', 'Sai. Nhóm số nhỏ chạy trước, nên bước đóng gói ở nhóm 2 sẽ được xếp trước hai kiểm tra ở nhóm 3.'],
    ], correct: ['A'], explanation: 'Trong cùng giai đoạn, runOrder bằng nhau cho phép chạy song song; số lớn hơn phải chờ nhóm số nhỏ hơn thành công. Vì vậy hai kiểm tra dùng nhóm 1 và đóng gói dùng nhóm 2.', tags: ['runOrder', 'parallelism'] },
    { section: 'ordering', en: 'Two parallel integration tests intermittently overwrite the same database rows. What is the strongest correction?', vi: 'Hai bộ kiểm thử tích hợp chạy song song thỉnh thoảng ghi đè cùng những bản ghi trong cơ sở dữ liệu. Cách xử lý nào giải quyết nguyên nhân trực tiếp nhất?', options: [
      ['Isolate test data or databases by execution', 'Tách dữ liệu kiểm thử hoặc cơ sở dữ liệu cho từng lần chạy', 'Đúng. Khi mỗi lần chạy có dữ liệu riêng, hai bộ kiểm thử không còn sửa cùng bản ghi và làm sai kết quả của nhau.'], ['Retry every failure while keeping the shared rows unchanged', 'Thử lại mỗi khi lỗi nhưng vẫn dùng chung các bản ghi', 'Sai. Thử lại có thể tình cờ thành công khi thời điểm chạy khác đi, nhưng việc hai bộ kiểm thử tranh chấp cùng dữ liệu vẫn còn.'], ['Add approval before compilation but keep test actions parallel', 'Thêm bước phê duyệt trước biên dịch, vẫn cho hai kiểm thử chạy song song', 'Sai. Phê duyệt trước khi chạy không tách dữ liệu và không ngăn hai bộ kiểm thử ghi đè nhau sau đó.'], ['Increase build compute size for both tests', 'Tăng tài nguyên máy build cho cả hai bộ kiểm thử', 'Sai. Máy chạy nhanh hơn vẫn có thể sửa cùng bản ghi. Vấn đề nằm ở dữ liệu dùng chung, không phải thiếu năng lực tính toán.'],
    ], correct: ['A'], explanation: 'Cấu hình pipeline cho phép chạy song song không bảo đảm công việc bên trong đã độc lập. Hãy tìm trạng thái dùng chung và tách dữ liệu gây tranh chấp giữa các lần chạy.', tags: ['integration-test', 'isolation'] },
    { section: 'ordering', en: 'Which TWO statements correctly describe action dependencies? Choose two.', vi: 'Hai nhận định nào mô tả đúng cách xác định thứ tự và phụ thuộc dữ liệu giữa các tác vụ? Chọn hai đáp án.', options: [
      ['Equal runOrder values allow parallel actions', 'Các tác vụ có cùng runOrder được phép chạy song song', 'Đúng. Trong cùng giai đoạn, cùng giá trị runOrder đặt các tác vụ vào một nhóm có thể chạy đồng thời.'], ['An input artifact must match a preceding output name', 'Tên gói đầu vào phải khớp tên gói do bước trước xuất ra', 'Đúng. Tác vụ nhận dữ liệu cần tham chiếu đúng đầu ra đã được tạo ở bước trước; CodePipeline dựa vào tên gói để nối chúng.'], ['Visual proximity creates a dependency', 'Đặt hai tác vụ cạnh nhau trên sơ đồ sẽ tạo quan hệ phụ thuộc', 'Sai. Bố cục hiển thị không thay đổi khai báo đầu vào, đầu ra hay runOrder; những cấu hình đó mới quyết định cách chạy.'], ['runOrder=0 is the first action group', 'Nhóm tác vụ đầu tiên dùng runOrder=0', 'Sai. runOrder yêu cầu số nguyên dương, nên không thể dùng 0 làm nhóm đầu tiên.'], ['All parallel actions share safe isolated data automatically', 'Mọi tác vụ song song đều tự động có dữ liệu riêng để chạy an toàn', 'Sai. CodePipeline không tự tách cơ sở dữ liệu hay trạng thái của ứng dụng. Người thiết kế phải bảo đảm các tác vụ không tranh chấp dữ liệu dùng chung.'],
    ], correct: ['A', 'B'], explanation: 'Đọc cả runOrder và đường chuyển giao gói dữ liệu để hiểu quan hệ giữa các bước. Hình vẽ chỉ giúp quan sát, còn cấu hình thực thi quyết định tác vụ nào chạy trước và nhận dữ liệu từ đâu.', tags: ['runOrder', 'artifact'] },
    { section: 'concurrency', en: 'Every release contains an ordered migration and must be processed. Which pipeline configuration best fits?', vi: 'Mỗi bản phát hành đều có bước chuyển đổi dữ liệu phải chạy đúng thứ tự, và không được bỏ qua bản nào. Cấu hình pipeline nào phù hợp nhất?', options: [
      ['V2 with QUEUED execution mode', 'Pipeline loại V2 với chế độ thực thi QUEUED', 'Đúng. QUEUED xếp các lần chạy vào hàng đợi, đáp ứng yêu cầu xử lý tuần tự thay vì để lần mới vượt lần trước.'], ['PARALLEL targeting the same database', 'PARALLEL triển khai vào cùng một cơ sở dữ liệu', 'Sai. Các lần chạy có thể hoàn tất khác thứ tự bắt đầu, nên bước chuyển đổi của bản sau có thể đụng dữ liệu trước khi bản trước xử lý xong.'], ['SUPERSEDED so waiting releases can be skipped', 'SUPERSEDED để có thể bỏ qua các bản đang chờ', 'Sai. Cơ chế thay thế lần chạy cũ có thể bỏ qua một bản đang chờ, trái với yêu cầu phải xử lý mọi bản phát hành.'], ['PARALLEL with a manual approval in every execution but no shared lock', 'PARALLEL có phê duyệt cho mỗi lần chạy nhưng không có cơ chế khóa chung', 'Sai. Việc duyệt độc lập từng lần chạy không bảo đảm thứ tự cập nhật vào cùng cơ sở dữ liệu sau khi các lần đó đều được cho phép.'],
    ], correct: ['A'], explanation: 'QUEUED giải quyết yêu cầu xếp hàng. Nhóm vẫn phải thiết kế bước chuyển đổi có thể chạy lại an toàn và bảo đảm cấu trúc dữ liệu tương thích với các phiên bản ứng dụng cần hỗ trợ.', tags: ['QUEUED', 'migration'] },
    { section: 'concurrency', en: 'A documentation pipeline only needs the newest revision and may discard older waiting executions. Which mode fits?', vi: 'Pipeline xuất bản tài liệu chỉ cần phiên bản mới nhất và được phép bỏ qua những lần chạy cũ còn chờ. Nên chọn chế độ nào?', options: [
      ['SUPERSEDED', 'SUPERSEDED', 'Đúng. Chế độ này cho phép lần chạy mới thay thế lần cũ đang chờ tại điểm dịch vụ cho phép, phù hợp khi không cần phát hành mọi phiên bản trung gian.'], ['QUEUED exclusively', 'Chỉ dùng QUEUED', 'Sai. QUEUED xử lý lần lượt cả những bản cũ vẫn nằm trong hàng đợi; đây không phải lựa chọn phù hợp nhất khi yêu cầu cho phép bỏ chúng để ưu tiên bản mới.'], ['PARALLEL with a shared destination and no ordering controls', 'PARALLEL cùng xuất bản đến một đích, không kiểm soát thứ tự', 'Sai. Bản cũ có thể hoàn tất sau và ghi đè tài liệu mới, khiến kết quả cuối cùng không còn là phiên bản mới nhất.'], ['PARALLEL followed by approving whichever execution finishes first', 'PARALLEL rồi duyệt lần chạy nào hoàn tất trước', 'Sai. Thời gian xử lý không cho biết phiên bản nào mới hơn, nên duyệt bản hoàn tất trước không bảo đảm xuất bản đúng phiên bản cần giữ.'],
    ], correct: ['A'], explanation: 'Dấu hiệu là chỉ cần phiên bản mới nhất và chấp nhận bỏ các bản còn chờ. SUPERSEDED hỗ trợ cách xử lý này, nhưng không có nghĩa mọi lệnh đang chạy đều bị hủy ngay lập tức.', tags: ['SUPERSEDED', 'execution'] },
    { section: 'concurrency', en: 'A platform needs independent preview stacks and explicitly does not need stage rollback. Which mode maximizes simultaneous executions?', vi: 'Nhóm nền tảng cần tạo nhiều stack xem trước độc lập và đã xác nhận không cần khôi phục ở cấp giai đoạn. Lựa chọn nào cho phép nhiều lần thực thi tiến hành đồng thời?', options: [
      ['V2 PARALLEL with isolated stack names', 'Pipeline V2 dùng PARALLEL, với tên stack riêng cho từng lần chạy', 'Đúng. PARALLEL cho phép các lần chạy tiến hành đồng thời; tên stack và tài nguyên riêng giúp chúng không cùng cập nhật một môi trường.'], ['QUEUED with one shared preview stack', 'QUEUED dùng chung một stack xem trước', 'Sai. Các lần chạy phải xếp hàng và chỉ có một stack dùng chung, nên không đáp ứng mục tiêu có nhiều môi trường xem trước cùng lúc.'], ['SUPERSEDED while requiring all previews to finish', 'SUPERSEDED nhưng yêu cầu mọi môi trường xem trước đều được tạo xong', 'Sai. Một số lần chạy đang chờ có thể bị thay thế, nên lựa chọn này không bảo đảm hoàn tất tất cả các bản xem trước.'], ['PARALLEL with one fixed database schema for all tests', 'PARALLEL dùng chung một cấu trúc cơ sở dữ liệu cho tất cả kiểm thử', 'Sai. Cấu trúc dữ liệu dùng chung khiến các lần chạy còn phụ thuộc nhau, không đáp ứng yêu cầu môi trường độc lập của tình huống.'],
    ], correct: ['A'], explanation: 'PARALLEL phù hợp khi từng lần chạy có tài nguyên độc lập và yêu cầu không phụ thuộc vào khôi phục ở cấp giai đoạn, vì chế độ này không hỗ trợ tính năng đó.', tags: ['PARALLEL', 'preview'] },
    { section: 'concurrency', en: 'Which TWO constraints matter before choosing PARALLEL mode? Choose two.', vi: 'Trước khi chọn PARALLEL, cần tính đến hai giới hạn hoặc yêu cầu nào sau đây? Chọn hai đáp án.', options: [
      ['Stage rollback is unavailable in this mode', 'Chế độ này không hỗ trợ khôi phục ở cấp giai đoạn', 'Đúng. Nếu quy trình phục hồi đang dựa vào stage rollback, nhóm phải đổi chế độ hoặc có phương án phục hồi riêng trước khi chuyển sang PARALLEL.'], ['Shared deployment targets require independent concurrency protection', 'Nếu triển khai vào đích dùng chung, cần cơ chế riêng để kiểm soát cập nhật đồng thời', 'Đúng. Nhiều lần chạy có thể cùng sửa tài nguyên đích; PARALLEL không tự bảo đảm thứ tự hay loại trừ việc cập nhật chồng nhau.'], ['All existing data migrations become reversible', 'Mọi bước chuyển đổi dữ liệu hiện có đều trở nên hoàn tác được', 'Sai. Chế độ thực thi không thay đổi cách dữ liệu được chuyển đổi. Khả năng hoàn tác phải được thiết kế và kiểm chứng riêng.'], ['It requires a V1 pipeline', 'PARALLEL yêu cầu pipeline loại V1', 'Sai. Chế độ PARALLEL yêu cầu pipeline loại V2; khai báo V1 không đáp ứng điều kiện sử dụng chế độ này.'], ['All executions finish in commit order', 'Mọi lần chạy đều hoàn tất theo thứ tự commit', 'Sai. Các lần chạy có thời gian xử lý khác nhau và tiến hành độc lập, nên bản bắt đầu sau có thể hoàn tất trước.'],
    ], correct: ['A', 'B'], explanation: 'Cần đánh giá cả tính năng dịch vụ không hỗ trợ lẫn tài nguyên ứng dụng có thể bị cập nhật đồng thời. Hai vấn đề này quyết định PARALLEL có phù hợp với cách triển khai và phục hồi của nhóm hay không.', tags: ['PARALLEL', 'rollback'] },
    { section: 'gates', en: 'A compliance approver receives only a generic approve link. What addition most improves the quality of the decision?', vi: 'Người phê duyệt về tuân thủ chỉ nhận được một đường dẫn duyệt chung, không có thông tin về bản phát hành. Cần bổ sung gì để người đó có cơ sở quyết định?', options: [
      ['The exact revision, test report, and target environment', 'Phiên bản mã nguồn cụ thể, báo cáo kiểm thử và môi trường sẽ triển khai', 'Đúng. Người duyệt cần biết đang cho phép phát hành nội dung nào, nội dung đó đã được kiểm tra ra sao và sẽ tác động đến môi trường nào.'], ['Only the latest test report, without binding it to the pending execution', 'Chỉ báo cáo kiểm thử mới nhất, không gắn với lần chạy đang chờ duyệt', 'Sai. Báo cáo mới nhất có thể thuộc commit khác; nếu không đối chiếu được với lần chạy đang chờ, người duyệt chưa biết bản này có đạt kiểm tra hay không.'], ['Only the build project name reused for every release', 'Chỉ tên dự án CodeBuild dùng chung cho mọi bản phát hành', 'Sai. Một dự án phục vụ nhiều lần build, nên tên dự án không xác định phiên bản và kết quả kiểm thử của lần đang duyệt.'], ['Only a link to the current default branch', 'Chỉ đường dẫn đến nhánh mặc định ở thời điểm hiện tại', 'Sai. Nhánh có thể đã nhận thay đổi sau khi pipeline lấy mã nguồn. Đường dẫn này cũng không cho biết môi trường đích của lần phát hành đang chờ.'],
    ], correct: ['A'], explanation: 'Một quyết định phê duyệt cần gắn với bản phát hành cụ thể. Phiên bản, kết quả kiểm thử và môi trường đích giúp người duyệt đánh giá đúng nội dung và phạm vi tác động.', tags: ['approval', 'governance'] },
    { section: 'gates', en: 'An engineer stops a pipeline after its deployment action modified a database. What should the engineer assume?', vi: 'Một kỹ sư dừng pipeline sau khi tác vụ triển khai đã thay đổi cơ sở dữ liệu. Kỹ sư cần hiểu trạng thái của thay đổi này như thế nào?', options: [
      ['The database change still needs an explicit recovery decision', 'Nhóm vẫn phải đánh giá thay đổi cơ sở dữ liệu và quyết định cách phục hồi', 'Đúng. Dừng pipeline không tự hoàn tác tác động đã xảy ra; nhóm phải kiểm tra dữ liệu hiện tại và chọn cách xử lý phù hợp.'], ['The database is automatically restored from backup', 'Cơ sở dữ liệu tự động được phục hồi từ bản sao lưu', 'Sai. Thao tác dừng CodePipeline không mặc định yêu cầu dịch vụ cơ sở dữ liệu khôi phục bản sao lưu.'], ['All deployed resources have been deleted', 'Tất cả tài nguyên đã triển khai đều bị xóa', 'Sai. Việc dừng luồng thực thi không tự gọi thao tác xóa những tài nguyên mà bước triển khai đã tạo hoặc cập nhật.'], ['The previous schema is guaranteed compatible', 'Cấu trúc dữ liệu của phiên bản trước chắc chắn vẫn tương thích', 'Sai. Khả năng chạy lại phiên bản cũ phụ thuộc vào thay đổi dữ liệu đã thực hiện và phải được kiểm chứng; trạng thái dừng không bảo đảm điều đó.'],
    ], correct: ['A'], explanation: 'CodePipeline điều phối công việc, còn thay đổi đã xảy ra nằm trong dịch vụ đích. Dừng điều phối và phục hồi dữ liệu là hai việc riêng; cần kiểm tra trạng thái thực tế trước khi quyết định khôi phục.', tags: ['stop', 'recovery'] },
    { section: 'gates', en: 'A test script catches all exceptions and exits 0. The pipeline is green despite failed assertions. What is the primary defect?', vi: 'Script kiểm thử bắt mọi ngoại lệ rồi trả mã thoát 0. Vì vậy pipeline báo thành công dù có điều kiện kiểm tra bị thất bại. Lỗi chính nằm ở đâu?', options: [
      ['The action success signal no longer represents test success', 'Trạng thái thành công của tác vụ không còn phản ánh kết quả kiểm thử', 'Đúng. Script luôn báo thành công cho công cụ chạy lệnh, khiến điều kiện kiểm tra không thể chặn một bản có lỗi.'], ['The report retention period is insufficient to execute the assertions', 'Thời hạn lưu báo cáo quá ngắn để thực thi các điều kiện kiểm tra', 'Sai. Thời hạn lưu quyết định báo cáo tồn tại bao lâu sau khi tạo, không sửa được cách script xử lý lỗi và trả mã thoát.'], ['The pipeline needs a manual approval instead of correcting the test command', 'Thêm phê duyệt thủ công thay vì sửa lệnh kiểm thử', 'Sai. Người duyệt vẫn nhận kết quả sai nếu script luôn trả 0. Cần sửa cách báo lỗi trước khi dựa vào kết quả đó để quyết định.'], ['Changing QUEUED to PARALLEL restores the swallowed exception', 'Đổi từ QUEUED sang PARALLEL để khôi phục ngoại lệ bị bỏ qua', 'Sai. Chế độ thực thi điều khiển nhiều lần chạy cùng lúc; nó không thay đổi cách script bắt ngoại lệ hay mã thoát của lệnh.'],
    ], correct: ['A'], explanation: 'Kiểm thử tự động phải trả mã lỗi khi không đạt. Nếu script che lỗi, trạng thái thành công của pipeline chỉ phản ánh lệnh đã trả 0, không chứng minh các điều kiện kiểm tra đều đúng.', tags: ['exit-code', 'quality-gate'] },
    { section: 'gates', en: 'Which TWO items belong in a practical rollback plan? Choose two.', vi: 'Kế hoạch khôi phục về phiên bản trước cần có hai nội dung nào sau đây? Chọn hai đáp án.', options: [
      ['A known previous artifact and health criteria', 'Gói phiên bản trước đã xác định rõ và tiêu chí kiểm tra ứng dụng sau khôi phục', 'Đúng. Nhóm cần biết chính xác gói nào sẽ chạy và cách xác nhận hệ thống đã hoạt động bình thường sau khi đưa gói đó trở lại.'], ['A decision for incompatible database changes', 'Phương án xử lý những thay đổi cơ sở dữ liệu không tương thích', 'Đúng. Đưa mã ứng dụng về bản cũ không tự phục hồi dữ liệu; kế hoạch phải giải quyết trường hợp bản cũ không đọc được cấu trúc hiện tại.'], ['An assumption that stopping reverses every action', 'Giả định dừng pipeline sẽ đảo ngược mọi thao tác', 'Sai. Tác động đã xảy ra trong dịch vụ đích vẫn có thể tồn tại sau khi dừng; kế hoạch dựa trên giả định này sẽ thiếu bước phục hồi cần thiết.'], ['Discarding execution history to reduce noise', 'Xóa lịch sử thực thi để bớt thông tin gây nhiễu', 'Sai. Lịch sử giúp xác định bản đã triển khai và thao tác đã xảy ra. Xóa nó làm việc điều tra và khôi phục khó hơn.'], ['Rebuilding the old branch without recording dependencies', 'Build lại nhánh cũ mà không ghi nhận phiên bản các thành phần phụ thuộc', 'Sai. Thành phần phụ thuộc có thể đã đổi, khiến gói build lại khác gói trước đây từng hoạt động tốt.'],
    ], correct: ['A', 'B'], explanation: 'Phục hồi cần một phiên bản đích xác định được, tiêu chí xác nhận kết quả và phương án cho dữ liệu đã thay đổi. Chỉ đổi lại mã ứng dụng chưa đủ khi cấu trúc dữ liệu không còn tương thích.', tags: ['rollback', 'database'] },
    { section: 'contract', en: 'The same commit is released twice after a transient infrastructure failure. Why retain both execution IDs?', vi: 'Sau một sự cố hạ tầng tạm thời, nhóm chạy quy trình phát hành lần thứ hai với cùng commit. Vì sao cần giữ mã của cả hai lần thực thi?', options: [
      ['They distinguish attempts and their logs, approvals, and outcomes', 'Để phân biệt từng lần thử cùng nhật ký, phê duyệt và kết quả tương ứng', 'Đúng. Hai lần chạy có thể dùng cùng mã nguồn nhưng kết quả và quá trình xử lý khác nhau; mỗi mã thực thi liên kết đến lịch sử riêng.'], ['They prove the commit has different source content', 'Để chứng minh hai lần dùng mã nguồn khác nhau', 'Sai. Một mã thực thi mới chỉ cho biết có lần chạy mới; nó không làm thay đổi nội dung của commit đã chọn.'], ['They replace the need for an artifact checksum', 'Để thay thế checksum của gói phần mềm', 'Sai. Mã lần chạy không được tính từ nội dung gói, nên không dùng để chứng minh hai gói có nội dung giống nhau.'], ['They guarantee the infrastructure failure cannot recur', 'Để bảo đảm sự cố hạ tầng sẽ không lặp lại', 'Sai. Việc lưu mã hỗ trợ truy vết sau sự cố, nhưng không khắc phục nguyên nhân hay ngăn hạ tầng gặp lỗi lần nữa.'],
    ], correct: ['A'], explanation: 'Khi truy vết một bản phát hành, cần lưu riêng phiên bản nguồn, nội dung gói và lần thực thi. Cùng một commit không có nghĩa mọi lần phát hành đều có chung nhật ký và kết quả.', tags: ['execution-ID', 'audit'] },
    { section: 'ordering', en: 'Security scanning consumes the built binary. A team places scanning parallel to compilation and supplies source only. What is missing?', vi: 'Công cụ quét bảo mật cần kiểm tra chương trình đã biên dịch. Tuy nhiên, nhóm cho bước quét chạy song song với biên dịch và chỉ cấp mã nguồn làm đầu vào. Thiết kế còn thiếu gì?', options: [
      ['A dependency on compilation and its binary output artifact', 'Cho bước quét chạy sau biên dịch và nhận gói chương trình do bước biên dịch tạo ra', 'Đúng. Dữ liệu cần quét chỉ tồn tại sau khi biên dịch xong; phải nối đúng gói đầu ra và đặt thứ tự chạy phù hợp.'], ['A manual approval before both parallel actions', 'Thêm phê duyệt trước cả hai tác vụ song song', 'Sai. Phê duyệt không tạo ra chương trình đã biên dịch và cũng không buộc bước quét chờ bước biên dịch hoàn tất.'], ['A separate scanner rebuild of the branch tip', 'Cho công cụ quét tự build riêng từ commit mới nhất của nhánh', 'Sai. Nhánh hoặc thành phần phụ thuộc có thể đã đổi, nên công cụ có thể quét một gói khác với gói pipeline chuẩn bị phát hành.'], ['A shared latest tag without an artifact contract', 'Dùng chung nhãn latest nhưng không khai báo rõ gói được chuyển giao', 'Sai. Nhãn có thể thay đổi và không thiết lập quan hệ đầu vào với bước biên dịch; bước quét vẫn chưa chắc nhận đúng nội dung cần kiểm tra.'],
    ], correct: ['A'], explanation: 'Chỉ chạy song song những bước không phụ thuộc dữ liệu của nhau. Ở đây bước quét cần đầu ra biên dịch, nên phải nhận gói đó và được xếp sau bước tạo gói.', tags: ['dependency', 'security-scan'] },
    { section: 'gates', en: 'A deployment failed because a regional endpoint was briefly unavailable; tests are deterministic and the endpoint has recovered. What is the most proportionate next action?', vi: 'Một lần triển khai thất bại vì đầu cuối dịch vụ trong Region bị gián đoạn ngắn. Các kiểm thử cho kết quả ổn định và đầu cuối đã hoạt động trở lại. Bước xử lý tiếp theo nào phù hợp nhất?', options: [
      ['Inspect partial effects, then retry the eligible failed action or stage', 'Kiểm tra những thay đổi đã xảy ra, rồi thử lại tác vụ hoặc giai đoạn lỗi nếu còn đủ điều kiện', 'Đúng. Cần biết lần triển khai dở dang đã làm gì trước khi thử lại, để tránh lặp cập nhật dữ liệu và tiếp tục với đúng gói đã kiểm thử.'], ['Automatically skip the failed deployment and mark production successful', 'Bỏ qua lần triển khai lỗi rồi đánh dấu môi trường chính thức đã thành công', 'Sai. Đầu cuối phục hồi chỉ cho biết có thể liên lạc với dịch vụ; chưa có bằng chứng rằng ứng dụng đã được triển khai đầy đủ và hoạt động bình thường.'], ['Rebuild with unpinned dependencies immediately', 'Build lại ngay mà không cố định phiên bản các thành phần phụ thuộc', 'Sai. Nguyên nhân là gián đoạn dịch vụ, không phải nội dung gói. Build lại có thể tạo gói khác và đưa thêm biến số vào việc xử lý.'], ['Rerun the full pipeline without checking whether deployment hooks already changed shared data', 'Chạy lại toàn bộ pipeline mà không kiểm tra các hook triển khai đã sửa dữ liệu dùng chung hay chưa', 'Sai. Một số thao tác có thể đã hoàn thành trước khi lỗi xảy ra; chạy lại thiếu kiểm tra có thể thực hiện chúng lần nữa và làm hỏng dữ liệu.'],
    ], correct: ['A'], explanation: 'Thử lại phù hợp khi đã hiểu nguyên nhân tạm thời và kiểm tra trạng thái thực tế. Cần xác định thao tác có thể chạy lại an toàn hay không trước khi yêu cầu dịch vụ thực hiện lần nữa.', tags: ['retry', 'incident'] },
  ]),
}
